-- Task lists, subtasks and repeating tasks.
--
-- Lists: a task belongs to one list (list_id); null = the built-in "My Tasks" list. Deleting a list
-- deletes its tasks.
--
-- Subtasks: a task row with parent_id set. One level only, no due date of its own, and the list
-- comes from the parent.
--
-- Repeating tasks use the same parent/child idea as repeating events: a series is ONE master row
-- (first due date plus the rule in `recurrence`), and the occurrences are generated by the app.
-- Only an occurrence that was changed, ticked off or deleted gets an exception row:
--   series_id      -> the master's id
--   original_date  -> which generated occurrence it replaces
--   cancelled      -> true when that occurrence was deleted
-- Deleting the master deletes its exceptions.

create table public.task_lists (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid()
    references auth.users (id) on delete cascade,
  name text not null check (length(trim(name)) > 0),
  created_at timestamptz not null default now()
);

alter table public.task_lists enable row level security;

create policy "Users manage their own task lists" on public.task_lists
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

grant select, insert, update, delete on public.task_lists to authenticated;

alter table public.tasks
  add column list_id uuid references public.task_lists (id) on delete cascade,
  add column parent_id uuid references public.tasks (id) on delete cascade,
  add column recurrence jsonb,
  -- Last date of a series that ends; null for "never ends". Lets range queries skip finished series.
  add column recurrence_ends_on date,
  add column series_id uuid references public.tasks (id) on delete cascade,
  add column original_date date,
  add column cancelled boolean not null default false;

alter table public.tasks
  add constraint tasks_exception_shape check ((series_id is null) = (original_date is null)),
  add constraint tasks_master_or_exception check (recurrence is null or series_id is null),
  add constraint tasks_master_has_date check (recurrence is null or due_date is not null),
  add constraint tasks_subtask_plain check (
    parent_id is null or (due_date is null and recurrence is null and series_id is null and list_id is null)
  );

-- One exception per occurrence
create unique index tasks_exception_unique on public.tasks (series_id, original_date)
  where series_id is not null;

create index tasks_parent_idx on public.tasks (parent_id) where parent_id is not null;
create index tasks_series_idx on public.tasks (series_id) where series_id is not null;
create index tasks_list_idx on public.tasks (list_id) where list_id is not null;

-- "Which series could reach this date range?"
create index tasks_master_idx on public.tasks (user_id, due_date)
  where recurrence is not null and series_id is null;

-- Every task the calendar needs for [range_start, range_end] (inclusive dates) in one round trip
-- (runs as the caller, so row-level security still applies):
--   * plain tasks due in the range
--   * series masters whose rule could reach the range, plus all of their exceptions
--     (an exception moved out of the range still has to hide the occurrence it replaces)
--   * exceptions that land in the range, plus their masters
-- Subtasks are not returned; the app loads them for the tasks it shows.
create function public.tasks_in_range(range_start date, range_end date)
returns setof public.tasks
language sql stable security invoker
as $$
  with masters as (
    select * from public.tasks
    where recurrence is not null and series_id is null
      and due_date <= range_end
      and (recurrence_ends_on is null or recurrence_ends_on >= range_start)
  ),
  moved_in as (
    select * from public.tasks
    where series_id is not null and due_date between range_start and range_end
  )
  select * from public.tasks
    where recurrence is null and series_id is null and parent_id is null
      and due_date between range_start and range_end
  union all
  select * from masters
  union all
  select * from public.tasks where series_id in (select id from masters)
  union all
  select * from public.tasks
    where id in (select series_id from moved_in) and id not in (select id from masters)
  union all
  select * from moved_in where series_id not in (select id from masters)
$$;

grant execute on function public.tasks_in_range(date, date) to authenticated;

-- Change what every occurrence of a series shares (title, notes, list, time). p_fields is JSON with those
-- columns. Exceptions keep their own date and completion, and follow the new time unless they were moved.
create function public.update_task_series(p_series uuid, p_fields jsonb)
returns void
language plpgsql security invoker
as $$
begin
  update public.tasks t
  set title = n.title, notes = n.notes, list_id = n.list_id, due_time = n.due_time
  from jsonb_populate_record(null::public.tasks, p_fields) as n
  where t.id = p_series and t.series_id is null;

  update public.tasks e
  set title = n.title, notes = n.notes, list_id = n.list_id,
      due_time = case when e.due_date = e.original_date then n.due_time else e.due_time end
  from jsonb_populate_record(null::public.tasks, p_fields) as n
  where e.series_id = p_series;
end
$$;

grant execute on function public.update_task_series(uuid, jsonb) to authenticated;

-- "This and following tasks": ends the series just before `p_split_on`, optionally starts a new series
-- from there, and moves the exceptions along with it, all in one transaction.
--   p_old_rule     the old master's rule, ending the day before the split; null when nothing is left
--                  before the split, which deletes the old master
--   p_new          the new master as JSON (title, notes, due_date, due_time, list_id, recurrence,
--                  recurrence_ends_on); null just deletes the tasks from the split on
-- Returns the new master's id (null when p_new is null).
create function public.split_task_series(
  p_series uuid,
  p_split_on date,
  p_old_rule jsonb,
  p_old_ends_on date,
  p_new jsonb
) returns uuid
language plpgsql security invoker
as $$
declare
  v_new uuid;
begin
  if p_new is not null then
    insert into public.tasks (title, notes, due_date, due_time, list_id, recurrence, recurrence_ends_on)
    select n.title, n.notes, n.due_date, n.due_time, n.list_id, n.recurrence, n.recurrence_ends_on
    from jsonb_populate_record(null::public.tasks, p_new) as n
    returning id into v_new;

    update public.tasks e
    set series_id = v_new, title = n.title, notes = n.notes, list_id = n.list_id,
        due_time = case when e.due_date = e.original_date then n.due_time else e.due_time end
    from jsonb_populate_record(null::public.tasks, p_new) as n
    where e.series_id = p_series and e.original_date >= p_split_on;
  else
    delete from public.tasks where series_id = p_series and original_date >= p_split_on;
  end if;

  if p_old_rule is null then
    delete from public.tasks where id = p_series and series_id is null;
  else
    update public.tasks
    set recurrence = p_old_rule, recurrence_ends_on = p_old_ends_on
    where id = p_series and series_id is null;
  end if;

  return v_new;
end
$$;

grant execute on function public.split_task_series(uuid, date, jsonb, date, jsonb) to authenticated;
